<script setup>
import {ref,computed,onMounted,onUnmounted} from 'vue';import {Head,Link,router,usePage} from '@inertiajs/vue3';import axios from 'axios';import {crew,modes,message} from '../art';import Feedback from '../Components/Feedback.vue';
const props=defineProps({attempt:Object,bookmarks:Array});const page=usePage(),data=ref(props.attempt),index=ref(0),busy=ref(false),error=ref(''),status=ref('All changes saved'),clock=ref(Date.now()),offset=new Date(props.attempt.server_now).getTime()-Date.now();
const q=computed(()=>data.value.items[index.value]);const ended=computed(()=>data.value.status!=='active');const remaining=computed(()=>data.value.deadline?Math.max(0,Math.ceil((new Date(data.value.deadline).getTime()-clock.value-offset)/1000)):null);
const timer=computed(()=>remaining.value===null?'Untimed':Math.floor(remaining.value/60)+':'+String(remaining.value%60).padStart(2,'0'));
let interval,heartbeat,lastAction=Date.now(),finishing=false;
function touch(){lastAction=Date.now()}
async function save(answer,check=false){busy.value=true;error.value='';status.value='Saving…';try{const r=await axios.post('/attempts/'+data.value.id+'/answer',{item_id:q.value.item_id,answer,check,revision:data.value.revision});data.value=r.data.attempt;page.props.achievement=r.data.achievement;page.props.community=r.data.community;status.value='All changes saved';}catch(e){error.value=message(e);status.value='Save failed. Retry your selection or reload.'}finally{busy.value=false}}
function finish(){if(finishing)return;finishing=true;router.post('/attempts/'+data.value.id+'/finish',{}, {onFinish:()=>{finishing=false;data.value=page.props.attempt}})}
onMounted(()=>{window.addEventListener('pointerdown',touch);window.addEventListener('keydown',touch);interval=setInterval(()=>{clock.value=Date.now();if(remaining.value===0&&!ended.value&&!busy.value)finish()},1000);heartbeat=setInterval(()=>{if(!document.hidden&&!ended.value)axios.post('/attempts/'+data.value.id+'/heartbeat',{active:Date.now()-lastAction<60000}).catch(()=>{})},15000)});
onUnmounted(()=>{clearInterval(interval);clearInterval(heartbeat);window.removeEventListener('pointerdown',touch);window.removeEventListener('keydown',touch)});
</script><template><Head :title="modes[data.mode]"/><div class="page-title"><div><p class="eyebrow">{{modes[data.mode]}} · {{data.status.replace('_',' ')}}</p><h1>{{ended?'Round complete':'Question '+(index+1)+' of '+data.items.length}}</h1><p v-if="ended">{{data.score}} / {{data.items.length}} correct · {{Math.round(data.score/data.items.length*100)}}%</p></div><strong class="timer">{{ended?'Finished':timer}}</strong></div>
<section v-if="ended&&data.mode==='fresh'" class="notice"><strong>🍣 Catch complete. Your study progress is saved.</strong><p>{{page.props.community?.habits.current}} study-day streak · {{page.props.community?.badge_count}} Passport stamps</p><Link class="button" href="/flashcards">Keep rolling with Memory Maki</Link> <Link href="/passport">See achievements</Link></section>
<p class="save-status" role="status">{{status}}</p><div v-if="error" class="notice error" role="alert">{{error}} <button @click="router.reload()">Reload saved attempt</button></div>
<div class="question-nav" aria-label="Question navigator"><button v-for="(item,i) in data.items" :key="item.item_id" :class="{selected:i===index,answered:item.answer}" @click="index=i" :aria-label="'Question '+(i+1)">{{i+1}}</button></div>
<article class="panel"><div class="row"><div class="subject-line"><img class="small-portrait" :src="crew[q.subject]?.image" :alt="crew[q.subject]?.name"><div><strong>{{q.subject}}</strong><small>{{q.topic}} · {{q.tier}} · {{q.id}}</small></div></div><button class="plain" @click="router.post('/bookmarks/'+q.id,{bookmarked:!bookmarks.includes(q.id)},{preserveScroll:true,onSuccess:()=>data=page.props.attempt})">{{bookmarks.includes(q.id)?'★ Saved':'☆ Save'}}</button></div>
<h2 class="pre question-stem">{{q.stem}}</h2><div class="options"><button v-for="(option,i) in q.options" :key="i" :disabled="busy||ended||q.checked" :class="{selected:q.answer===String.fromCharCode(65+i),correct:q.key===String.fromCharCode(65+i)}" @click="save(String.fromCharCode(65+i))"><strong>{{String.fromCharCode(65+i)}}.</strong> {{option}}</button></div>
<button v-if="!ended&&!q.checked&&['fresh','tutor'].includes(data.mode)" class="primary" :disabled="busy||!q.answer" @click="save(q.answer,true)">Check answer</button><Feedback :question="q"/><p v-if="ended&&!q.key" class="notice">Your administrator has not released the answer explanations yet.</p>
<div class="row spaced"><button :disabled="index===0||busy" @click="index--">Previous</button><button :disabled="index===data.items.length-1||busy" @click="index++">Next</button></div></article>
<details v-if="!ended" class="panel"><summary>Finish this round</summary><p>{{data.mode==='fresh'?'Answer all ten questions to earn today’s stamp.':'Submit your saved answers. Unanswered questions count as incorrect in the set score.'}}</p><button class="primary" :disabled="busy" @click="finish">Submit round</button></details>
</template>
